using cl2j.Database.DataAnnotations;
using cl2j.Database.Databases;
using cl2j.Database.Exceptions;
using Microsoft.Extensions.Logging.Abstractions;
using Xunit;

namespace cl2j.Database.IntegrationTests
{
    /// <summary>
    ///     What each <see cref="KeyType"/> means at run time, and that <c>NewKey</c>, <c>Insert</c>
    ///     and <c>BulkInsert</c> agree on it (issue #69).
    ///
    ///     <para>
    ///     <see cref="KeyType.AutoGeneratedKey"/>: the library generates the value on insert and
    ///     replaces one already set. <see cref="KeyType.SelfGeneratedKey"/>: the caller supplies it,
    ///     insert sends it as set. <see cref="KeyType.Key"/>: an int or long is a server identity
    ///     that insert writes back onto the entity, a Guid is a server default, anything else is
    ///     supplied by the caller. <c>NewKey</c> serves the two generated string kinds.
    ///     </para>
    /// </summary>
    public abstract class KeySemanticsTestsBase(IDatabaseFixture fixture) : IAsyncLifetime
    {
        private static readonly Type[] Tables =
        [
            typeof(KsAutoRow), typeof(KsSelfRow), typeof(KsIntRow), typeof(KsLongRow), typeof(KsGuidRow), typeof(KsStringRow)
        ];

        public async Task InitializeAsync()
        {
            await using var connection = await fixture.OpenAsync();
            foreach (var table in Tables)
                await connection.DropTableIfExists(table, CancellationToken.None);

            await connection.CreateTable<KsAutoRow>();
            await connection.CreateTable<KsSelfRow>();
            await connection.CreateTable<KsIntRow>();
            await connection.CreateTable<KsLongRow>();
            await connection.CreateTable<KsGuidRow>();
            await connection.CreateTable<KsStringRow>();
        }

        public async Task DisposeAsync()
        {
            await using var connection = await fixture.OpenAsync();
            foreach (var table in Tables)
                await connection.DropTableIfExists(table, CancellationToken.None);
        }

        #region AutoGeneratedKey

        [Fact]
        public async Task NewKey_gives_a_prefixed_key_for_an_auto_generated_key_entity()
        {
            await using var connection = await fixture.OpenAsync();

            var key = await connection.NewKey<KsAutoRow>();

            Assert.StartsWith("ksa_", key, StringComparison.Ordinal);
        }

        [Fact]
        public async Task NewKey_through_IDatabase_gives_a_key_for_an_auto_generated_key_entity()
        {
            var database = fixture.CreateDatabase(new DatabaseOptions(), NullLogger.Instance);

            var key = await database.NewKey<KsAutoRow>();

            Assert.StartsWith("ksa_", key, StringComparison.Ordinal);
        }

        [Fact]
        public async Task Insert_fills_in_an_auto_generated_key()
        {
            await using var connection = await fixture.OpenAsync();
            var row = new KsAutoRow { Label = "x" };

            await connection.Insert(row);

            Assert.StartsWith("ksa_", row.Id, StringComparison.Ordinal);
            Assert.Equal("x", (await connection.QueryKey<KsAutoRow>(row.Id))!.Label);
        }

        [Fact]
        public async Task Insert_replaces_an_auto_generated_key_set_beforehand()
        {
            await using var connection = await fixture.OpenAsync();
            var row = new KsAutoRow { Id = "mine", Label = "x" };

            await connection.Insert(row);

            Assert.NotEqual("mine", row.Id);
            Assert.StartsWith("ksa_", row.Id, StringComparison.Ordinal);
            Assert.Null(await connection.QueryKey<KsAutoRow>("mine"));
            Assert.NotNull(await connection.QueryKey<KsAutoRow>(row.Id));
        }

        [Fact]
        public async Task BulkInsert_fills_in_every_auto_generated_key()
        {
            await using var connection = await fixture.OpenAsync();
            var rows = Enumerable.Range(0, 5).Select(i => new KsAutoRow { Label = $"row{i}" }).ToList();

            await connection.BulkInsert(rows);

            Assert.All(rows, r => Assert.StartsWith("ksa_", r.Id, StringComparison.Ordinal));
            Assert.Equal(5, rows.Select(r => r.Id).Distinct().Count());
            foreach (var row in rows)
                Assert.Equal(row.Label, (await connection.QueryKey<KsAutoRow>(row.Id))!.Label);
        }

        #endregion

        #region SelfGeneratedKey

        [Fact]
        public async Task NewKey_gives_a_prefixed_key_for_a_self_generated_key_entity_and_two_calls_differ()
        {
            await using var connection = await fixture.OpenAsync();

            var first = await connection.NewKey<KsSelfRow>();
            var second = await connection.NewKey<KsSelfRow>();

            Assert.StartsWith("kss_", first, StringComparison.Ordinal);
            Assert.StartsWith("kss_", second, StringComparison.Ordinal);
            Assert.NotEqual(first, second);
        }

        [Fact]
        public async Task Insert_sends_a_self_generated_key_as_set()
        {
            await using var connection = await fixture.OpenAsync();
            var key = await connection.NewKey<KsSelfRow>();
            var row = new KsSelfRow { Id = key, Label = "x" };

            await connection.Insert(row);

            Assert.Equal(key, row.Id);
            Assert.Equal("x", (await connection.QueryKey<KsSelfRow>(key))!.Label);
        }

        [Fact]
        public async Task BulkInsert_sends_self_generated_keys_as_set()
        {
            await using var connection = await fixture.OpenAsync();
            var rows = new List<KsSelfRow>();
            for (var i = 0; i < 5; i++)
                rows.Add(new KsSelfRow { Id = await connection.NewKey<KsSelfRow>(), Label = $"row{i}" });
            var keys = rows.Select(r => r.Id).ToList();

            await connection.BulkInsert(rows);

            Assert.Equal(keys, rows.Select(r => r.Id).ToList());
            foreach (var row in rows)
                Assert.Equal(row.Label, (await connection.QueryKey<KsSelfRow>(row.Id))!.Label);
        }

        #endregion

        #region Key: identity

        [Fact]
        public async Task Insert_writes_the_int_identity_back_onto_the_entity()
        {
            await using var connection = await fixture.OpenAsync();
            var row = new KsIntRow { Label = "first" };

            await connection.Insert(row);
            var other = await connection.Insert<KsIntRow, int>(new KsIntRow { Label = "second" });

            Assert.True(row.Id > 0);
            Assert.NotEqual(row.Id, other);
            Assert.Equal("first", (await connection.QueryKey<KsIntRow>(row.Id))!.Label);
            Assert.Equal("second", (await connection.QueryKey<KsIntRow>(other))!.Label);
        }

        [Fact]
        public async Task Insert_writes_the_long_identity_back_onto_the_entity()
        {
            await using var connection = await fixture.OpenAsync();
            var row = new KsLongRow { Label = "first" };

            await connection.Insert(row);
            var other = await connection.Insert<KsLongRow, long>(new KsLongRow { Label = "second" });

            Assert.True(row.Id > 0);
            Assert.NotEqual(row.Id, other);
            Assert.Equal("first", (await connection.QueryKey<KsLongRow>(row.Id))!.Label);
            Assert.Equal("second", (await connection.QueryKey<KsLongRow>(other))!.Label);
        }

        [Fact]
        public async Task Insert_through_IDatabase_returns_the_entity_with_its_identity()
        {
            var database = fixture.CreateDatabase(new DatabaseOptions(), NullLogger.Instance);

            var first = await database.Insert(new KsIntRow { Label = "a" });
            var second = await database.Insert(new KsIntRow { Label = "b" });

            Assert.True(first.Id > 0);
            Assert.True(second.Id > 0);
            Assert.NotEqual(first.Id, second.Id);
        }

        [Fact]
        public async Task NewKey_throws_for_an_identity_key_entity()
        {
            await using var connection = await fixture.OpenAsync();

            await Assert.ThrowsAsync<DatabaseException>(() => connection.NewKey<KsIntRow>());
            await Assert.ThrowsAsync<DatabaseException>(() => connection.NewKey<KsLongRow>());
        }

        #endregion

        #region Key: Guid and string

        [Fact]
        public async Task Insert_leaves_a_Guid_key_to_the_server()
        {
            await using var connection = await fixture.OpenAsync();

            await connection.Insert(new KsGuidRow { Label = "guid" });

            var read = Assert.Single(await connection.Query<KsGuidRow>(new { Label = "guid" }));
            Assert.NotEqual(Guid.Empty, read.Id);
        }

        [Fact]
        public async Task NewKey_throws_for_a_Guid_key_entity()
        {
            await using var connection = await fixture.OpenAsync();

            await Assert.ThrowsAsync<DatabaseException>(() => connection.NewKey<KsGuidRow>());
        }

        [Fact]
        public async Task Insert_sends_a_string_key_as_set()
        {
            await using var connection = await fixture.OpenAsync();

            await connection.Insert(new KsStringRow { Code = "chosen", Label = "x" });

            Assert.Equal("x", (await connection.QueryKey<KsStringRow>("chosen"))!.Label);
        }

        [Fact]
        public async Task NewKey_throws_for_a_string_key_entity()
        {
            await using var connection = await fixture.OpenAsync();

            await Assert.ThrowsAsync<DatabaseException>(() => connection.NewKey<KsStringRow>());
        }

        #endregion
    }

    [Table("KsAuto")]
    public sealed class KsAutoRow
    {
        [Column(Name = "Id", Key = KeyType.AutoGeneratedKey, Length = 40, KeyPrefix = "ksa_")]
        public string Id { get; set; } = string.Empty;

        [Column(Name = "Label", Length = 50)]
        public string Label { get; set; } = string.Empty;
    }

    [Table("KsSelf")]
    public sealed class KsSelfRow
    {
        [Column(Name = "Id", Key = KeyType.SelfGeneratedKey, Length = 40, KeyPrefix = "kss_")]
        public string Id { get; set; } = string.Empty;

        [Column(Name = "Label", Length = 50)]
        public string Label { get; set; } = string.Empty;
    }

    [Table("KsInt")]
    public sealed class KsIntRow
    {
        [Column(Name = "Id", Key = KeyType.Key)]
        public int Id { get; set; }

        [Column(Name = "Label", Length = 50)]
        public string Label { get; set; } = string.Empty;
    }

    [Table("KsLong")]
    public sealed class KsLongRow
    {
        [Column(Name = "Id", Key = KeyType.Key)]
        public long Id { get; set; }

        [Column(Name = "Label", Length = 50)]
        public string Label { get; set; } = string.Empty;
    }

    [Table("KsGuid")]
    public sealed class KsGuidRow
    {
        [Column(Name = "Id", Key = KeyType.Key)]
        public Guid Id { get; set; }

        [Column(Name = "Label", Length = 50)]
        public string Label { get; set; } = string.Empty;
    }

    [Table("KsString")]
    public sealed class KsStringRow
    {
        [Column(Name = "Code", Key = KeyType.Key, Length = 50)]
        public string Code { get; set; } = string.Empty;

        [Column(Name = "Label", Length = 50)]
        public string Label { get; set; } = string.Empty;
    }
}
